def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    rectangles = []

    # Find dense, non-background rectangles that represent the solid objects.
    for color in counts:
        if color == bg:
            continue
        for r1 in range(h):
            for r2 in range(r1 + 1, h):
                for c1 in range(w):
                    for c2 in range(c1 + 1, w):
                        area = (r2 - r1 + 1) * (c2 - c1 + 1)
                        n = sum(grid[r][c] == color
                                for r in range(r1, r2 + 1)
                                for c in range(c1, c2 + 1))
                        if n / area >= 0.80:
                            rectangles.append((color, r1, r2, c1, c2))

    # Keep maximal qualifying rectangles for each color.
    chosen = []
    for box in rectangles:
        color, r1, r2, c1, c2 = box
        contained = any(
            other[0] == color and other != box and
            other[1] <= r1 and other[2] >= r2 and
            other[3] <= c1 and other[4] >= c2
            for other in rectangles
        )
        if not contained:
            chosen.append(box)

    out = [[bg for _ in range(w)] for _ in range(h)]
    for color, r1, r2, c1, c2 in chosen:
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                out[r][c] = color
    return out
